//! 🗓️ Exact authored schedule families, hourly/daily order and holiday presence.
use super::*;
use crate::schedule::*;
const VALUE:&[FloatColumn]=&[FloatColumn::Binary64(4)];
const HOUR:&[FloatColumn]=&[FloatColumn::Binary64(3)];
const LIMITS:&[FloatColumn]=&[FloatColumn::Binary64(1),FloatColumn::Binary64(2)];
pub(super)fn project(s:&ScheduleSet,p:&mut Projection<'_,'_>)->Result<(),String>{
 for(n,v)in s.constants.iter().enumerate(){emit(p,"energy_constant_schedule",n,&[i(v.id.0),Cell::Real(v.value)],VALUE)?;}
 for(n,v)in s.daily.iter().enumerate(){let mode=match v.interpolation{ScheduleInterpolation::Continuous=>"Continuous",ScheduleInterpolation::Discrete=>"Discrete"};let id=emit(p,"energy_daily_schedule",n,&[i(v.id.0),Cell::Text(mode)],&[])?;for(hour,value)in v.hourly_values.iter().enumerate(){edge(p,"energy_daily_hour",id,hour,&[Cell::Real(*value)],HOUR)?;}if let Some(limits)=v.limits{insert_key_ieee754(p,"energy_daily_limits",id,&[Cell::Real(limits.min),Cell::Real(limits.max)],LIMITS)?;}}
 for(n,v)in s.weekly.iter().enumerate(){let id=emit(p,"energy_weekly_schedule",n,&[i(v.id.0)],&[])?;for(day,daily)in v.daily_schedule_ids.iter().enumerate(){edge(p,"energy_weekly_day",id,day,&[i(daily.0)],&[])?;}}
 for(n,v)in s.annual.iter().enumerate(){let id=emit(p,"energy_annual_schedule",n,&[i(v.id.0),i(v.default_daily_schedule_id.0),optional_schedule(v.holiday_daily_schedule_id)],&[])?;for(n,rule)in v.rules.iter().enumerate(){edge(p,"energy_annual_rule",id,n,&[i(u32::from(rule.start_month)),i(u32::from(rule.start_day)),i(u32::from(rule.end_month)),i(u32::from(rule.end_day)),i(rule.daily_schedule_id.0)],&[])?;}for(n,(year,month,day))in v.holiday_dates.iter().enumerate(){edge(p,"energy_annual_holiday",id,n,&[i(u32::from(*year)),i(u32::from(*month)),i(u32::from(*day))],&[])?;}}
 for(n,v)in s.time_series.iter().enumerate(){let id=emit(p,"energy_time_series_schedule",n,&[i(v.id.0),i(v.timestep_seconds)],&[])?;for(n,value)in v.values.iter().enumerate(){edge(p,"energy_time_series_value",id,n,&[Cell::Real(*value)],HOUR)?;}}Ok(())
}
fn unsigned8(r:FloatRow<'_>,n:usize)->Result<u8,String>{u8::try_from(u32_value(r,n)?).map_err(|_|"Energy schedule unsigned8 differs".into())}
pub(super)fn reconstruct(r:&mut Reader<'_,'_,'_>)->Result<ScheduleSet,String>{
 let mut s=ScheduleSet::default();
 for v in r.rows("energy_constant_schedule",1,5,VALUE)?{s.constants.push(ConstantSchedule{id:schedule(v,3)?,value:v.real(4)?});}
 for v in r.rows("energy_daily_schedule",1,5,&[])?{let interpolation=match v.text(4)?{"Continuous"=>ScheduleInterpolation::Continuous,"Discrete"=>ScheduleInterpolation::Discrete,_=>return Err("Energy schedule interpolation differs".into())};let hours=r.rows("energy_daily_hour",v.rowid,4,HOUR)?;if hours.len()!=24{return Err("Energy daily schedule has exactly24hours".into())}let mut hourly_values=[0.0;24];for(n,hour)in hours.into_iter().enumerate(){hourly_values[n]=hour.real(3)?;}let limits=r.optional("energy_daily_limits",v.rowid,3,LIMITS)?.map(|row|Ok::<_,String>(ScheduleLimits{min:row.real(1)?,max:row.real(2)?})).transpose()?;s.daily.push(DailySchedule{id:schedule(v,3)?,hourly_values,interpolation,limits});}
 for v in r.rows("energy_weekly_schedule",1,4,&[])?{let days=r.rows("energy_weekly_day",v.rowid,4,&[])?;if days.len()!=7{return Err("Energy weekly schedule has exactly7days".into())}let mut daily_schedule_ids=[ScheduleId(0);7];for(n,day)in days.into_iter().enumerate(){daily_schedule_ids[n]=schedule(day,3)?;}s.weekly.push(WeeklySchedule{id:schedule(v,3)?,daily_schedule_ids});}
 for v in r.rows("energy_annual_schedule",1,6,&[])?{let mut rules=Vec::new();for rule in r.rows("energy_annual_rule",v.rowid,8,&[])?{rules.push(CompactScheduleRule{start_month:unsigned8(rule,3)?,start_day:unsigned8(rule,4)?,end_month:unsigned8(rule,5)?,end_day:unsigned8(rule,6)?,daily_schedule_id:schedule(rule,7)?});}let mut holiday_dates=Vec::new();for holiday in r.rows("energy_annual_holiday",v.rowid,6,&[])?{holiday_dates.push((u16::try_from(u32_value(holiday,3)?).map_err(|_|"Energy holiday year exceeds unsigned16")?,unsigned8(holiday,4)?,unsigned8(holiday,5)?));}s.annual.push(AnnualSchedule{id:schedule(v,3)?,rules,default_daily_schedule_id:schedule(v,4)?,holiday_daily_schedule_id:optional_schedule_value(v,5)?,holiday_dates});}
 for v in r.rows("energy_time_series_schedule",1,5,&[])?{let mut values=Vec::new();for value in r.rows("energy_time_series_value",v.rowid,4,HOUR)?{values.push(value.real(3)?);}s.time_series.push(TimeSeriesSchedule{id:schedule(v,3)?,values,timestep_seconds:u32_value(v,4)?});}Ok(s)
}
